create function pg_temp.journey(reordered boolean default false) returns jsonb language sql as $$select jsonb_build_object('schemaVersion',1,'stages',jsonb_agg(jsonb_build_object('id',kind,'kind',kind,'label',kind,'enabled',kind<>'options') order by n)) from unnest(case when reordered then array['service','options','information','schedule','review_payment','confirmation'] else array['service','options','schedule','information','review_payment','confirmation'] end) with ordinality s(kind,n)$$;
create function pg_temp.save(r bigint default 0,reordered boolean default false,f uuid default '70000000-0000-4000-8000-000000000004') returns jsonb language sql as $$select public.save_paid_journey_draft('70000000-0000-4000-8000-000000000001','70000000-0000-4000-8000-000000000002',f,'70000000-0000-4000-8000-000000000003',r,'Journey','{"accentColor":"#4f46e5","layout":"stacked"}',pg_temp.journey(reordered))$$;
create function pg_temp.publish(r bigint default 1,v uuid default '70000000-0000-4000-8000-000000000005',i uuid default '70000000-0000-4000-8000-000000000006',o jsonb default '["https://checkout.example.test"]',approved jsonb default '["https://checkout.example.test"]',a uuid default '70000000-0000-4000-8000-000000000001',t uuid default '70000000-0000-4000-8000-000000000002',f uuid default '70000000-0000-4000-8000-000000000004') returns jsonb language sql as $$select public.publish_paid_journey_draft(a,t,f,r,v,i,o,approved)$$;
select pg_temp.save();
select pg_temp.publish();
create function pg_temp.owner_read(a uuid default '70000000-0000-4000-8000-000000000001',t uuid default '70000000-0000-4000-8000-000000000002',f uuid default '70000000-0000-4000-8000-000000000004') returns jsonb language sql as $$select public.get_paid_journey_owner_publication(a,t,f)$$;
select pg_temp.assert(pg_temp.owner_read()->>'draftRevision'='1' and pg_temp.owner_read()->>'versionId'=pg_temp.owner_read()#>>'{render,versionId}','immutable source receipt bound');
select pg_temp.assert(not(pg_temp.owner_read() ?| array['actorId','sessionToken','customer','customerId','replayed']),'no private/customer/writer metadata');
select pg_temp.reject($q$select pg_temp.owner_read(a=>'70000000-0000-4000-8000-000000000099')$q$,'42501');
select pg_temp.reject($q$select pg_temp.owner_read(t=>'70000000-0000-4000-8000-000000000098')$q$,'42501');
set local role anon;select pg_temp.reject($q$select public.get_paid_journey_owner_publication('70000000-0000-4000-8000-000000000001','70000000-0000-4000-8000-000000000002','70000000-0000-4000-8000-000000000004')$q$,'42501');reset role;
update public.tenant_members set role='BUSINESS_STAFF' where tenant_id='70000000-0000-4000-8000-000000000002';select pg_temp.reject($q$select pg_temp.owner_read()$q$,'42501');
update public.tenant_members set role='BUSINESS_OWNER' where tenant_id='70000000-0000-4000-8000-000000000002';
update public.tenants set status='suspended' where id='70000000-0000-4000-8000-000000000002';select pg_temp.reject($q$select pg_temp.owner_read()$q$,'42501');update public.tenants set status='active' where id='70000000-0000-4000-8000-000000000002';
update public.services set active=false where id='70000000-0000-4000-8000-000000000003';select pg_temp.reject($q$select pg_temp.owner_read()$q$,'42501');update public.services set active=true,base_price=12600 where id='70000000-0000-4000-8000-000000000003';select pg_temp.reject($q$select pg_temp.owner_read()$q$,'40001');update public.services set base_price=12500 where id='70000000-0000-4000-8000-000000000003';
select public.create_staging_business('70000000-0000-4000-8000-000000000001','70000000-0000-4000-8000-000000000090','Detailing','journey-reader-detailing','UTC','USD','AUTO_DETAILING','journey_reader_detailing');
